from django import forms
from django.core.exceptions import ValidationError

def validate_no_profanity(value):
    if "badword" in value.lower():
        raise ValidationError("Please keep it civil.")

class SignupForm(forms.Form):
    email = forms.EmailField()
    password = forms.CharField(widget=forms.PasswordInput)
    confirm = forms.CharField(widget=forms.PasswordInput, label="Repeat password")
    username = forms.CharField(validators=[validate_no_profanity])

    def clean_email(self):
        email = self.cleaned_data["email"].lower()
        if User.objects.filter(email__iexact=email).exists():
            raise ValidationError("An account with this email already exists.")
        return email

    def clean(self):
        cleaned = super().clean()
        password = cleaned.get("password")
        confirm = cleaned.get("confirm")
        if password and confirm and password != confirm:
            self.add_error("confirm", "The passwords do not match.")
        return cleaned

from django import forms
from .models import Post

class PostForm(forms.ModelForm):
    class Meta:
        model = Post
        fields = ["title", "slug", "body", "status", "tags"]
        widgets = {
            "body": forms.Textarea(attrs={"rows": 14}),
            "status": forms.Select(attrs={"class": "select"}),
        }
        labels = {"body": "Article body"}
        help_texts = {"slug": "Used in the URL. Lowercase, hyphens only."}

    def clean_slug(self):
        slug = self.cleaned_data["slug"]
        if slug in {"admin", "new", "edit"}:
            raise forms.ValidationError("That slug is reserved.")
        return slug

